parameters.jsCode:
const a = $input.all()[0].json;
const start = new Date(a.startTime || a.start || a.scheduledAt);
const now = new Date();
const minutesToStart = Math.round((start - now) / 60000);

let stage = null;
if (minutesToStart > 23 * 60 && minutesToStart <= 25 * 60) stage = 'T_MINUS_24H';
else if (minutesToStart > 50 && minutesToStart <= 70) stage = 'T_MINUS_1H';
else if (minutesToStart > 10 && minutesToStart <= 20) stage = 'T_MINUS_15M';

if (!stage) return [{ json: { skip: true, reason: `Outside reminder windows (${minutesToStart}min to start)` } }];

const channelPlan = {
  T_MINUS_24H: ['EMAIL', 'WHATSAPP'],
  T_MINUS_1H: ['PUSH', 'IN_APP'],
  T_MINUS_15M: ['PUSH']
}[stage];

return [{
  json: {
    skip: false,
    stage,
    channelPlan,
    minutesToStart,
    appointmentId: a.id,
    tenantId: a.tenantId,
    customerEmail: a.customerEmail,
    customerPhone: a.customerPhone,
    customerId: a.customerId,
    employeeEmail: a.employeeEmail,
    title: a.title || 'Dayjoy Appointment',
    startTime: a.startTime || a.start,
    location: a.meetingLink || a.location || ''
  }
}];

